// Service Worker para UBICA-RICK PWA v6.2
const CACHE_NAME = 'ubica-rick-v6.2-pwa';

const ICON_192_DATA = "data:image/png;base64,";
const ICON_512_DATA = "data:image/png;base64,";
const FAVICON_DATA = "data:image/png;base64,";

const ASSETS_TO_CACHE = [
  './',
  './index.html',
  './manifest.json',
  './sw.js'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      // Pre-cargar los iconos directamente en caché para garantizar que nunca den 404
      const p192 = fetch(ICON_192_DATA).then(res => cache.put('./icon-192.png', res.clone()).then(() => cache.put('icon-192.png', res)));
      const p512 = fetch(ICON_512_DATA).then(res => cache.put('./icon-512.png', res.clone()).then(() => cache.put('icon-512.png', res)));
      const pFav = fetch(FAVICON_DATA).then(res => cache.put('./favicon.png', res.clone()).then(() => cache.put('favicon.png', res)));

      const pAssets = Promise.allSettled(
        ASSETS_TO_CACHE.map((url) => {
          return fetch(url).then((res) => {
            if (res && res.status === 200) {
              return cache.put(url, res);
            }
          }).catch(() => {});
        })
      );
      return Promise.allSettled([p192, p512, pFav, pAssets]);
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Interceptar peticiones: Si icon-192.png o icon-512.png no están en el servidor, servir desde memoria
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  if (!event.request.url.startsWith('http')) return;

  const url = event.request.url;

  // Intercepción inteligente de iconos para que NUNCA den 404
  if (url.includes('icon-192.png')) {
    event.respondWith(
      fetch(event.request)
        .then(res => (res && res.status === 200) ? res : fetch(ICON_192_DATA))
        .catch(() => caches.match(event.request).then(m => m || fetch(ICON_192_DATA)))
    );
    return;
  }

  if (url.includes('icon-512.png')) {
    event.respondWith(
      fetch(event.request)
        .then(res => (res && res.status === 200) ? res : fetch(ICON_512_DATA))
        .catch(() => caches.match(event.request).then(m => m || fetch(ICON_512_DATA)))
    );
    return;
  }

  if (url.includes('favicon.png')) {
    event.respondWith(
      fetch(event.request)
        .then(res => (res && res.status === 200) ? res : fetch(FAVICON_DATA))
        .catch(() => caches.match(event.request).then(m => m || fetch(FAVICON_DATA)))
    );
    return;
  }

  event.respondWith(
    fetch(event.request)
      .then((networkResponse) => {
        if (networkResponse && networkResponse.status === 200) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseToCache);
          });
        }
        return networkResponse;
      })
      .catch(() => {
        return caches.match(event.request).then((cachedResponse) => {
          if (cachedResponse) return cachedResponse;
          if (event.request.headers.get('accept') && event.request.headers.get('accept').includes('text/html')) {
            return caches.match('./index.html');
          }
        });
      })
  );
});
